-- =====================================================
-- SHOPEASY DATABASE (Sales and Customer Analysis project)
-- Tables: products (26 rows), orders (100 rows)
-- Safe to re-run any time: it resets everything.
-- =====================================================

DROP DATABASE IF EXISTS shopeasy_db;
CREATE DATABASE shopeasy_db;
USE shopeasy_db;

CREATE TABLE products (
    product_id    INT,
    product_name  VARCHAR(50),
    category      VARCHAR(30),
    brand         VARCHAR(30),
    price         DECIMAL(10,2),
    stock_qty     INT,
    launch_date   DATE,
    rating        DECIMAL(2,1)
);


CREATE TABLE orders (
    order_id         INT,
    order_date       DATE,
    customer_name    VARCHAR(40),
    city             VARCHAR(30),
    category         VARCHAR(30),
    product_name     VARCHAR(50),
    quantity         INT,
    unit_price       DECIMAL(10,2),
    discount_percent DECIMAL(5,2),
    total_amount     DECIMAL(12,2),
    payment_mode     VARCHAR(20),
    order_status     VARCHAR(20),
    delivery_days    INT
);

